// Generated by scripts/embed-workflow-instructions.ts — do not edit manually.
export const INSTRUCTION_BODIES: Record<string, string> = {
  "agent.guide.page_authoring.md": "# agent.guide.page_authoring\n\nReference for authoring json-render pages with `create_page` / `update_page`.\nLoad this when you need the page format; it is not a task to route.\n\n## Spec shape\n\nA page's `spec` is `{ root, elements }`:\n\n- `elements`: a map of `elementId -> { type, props?, children? }`.\n- `type`: a component key — call `list_page_components` for the catalog and\n  `get_page_component(key)` for a component's props + a copy-paste example.\n  - `children`: array of `elementId`s (only for container components like\n  Section, Card, Resizable, Grid, Form).\n- `root`: the top-level `elementId` to render.\n\n## Bindings (load graph data)\n\n`bindings` is a map of `bindingKey -> def`. An element references one via\n`props.binding`. Kinds:\n\n- `{ kind: \"query\", catalogKey, filter? }` — many nodes of a type (tables/lists).\n- `{ kind: \"singleton\", catalogKey, ensure? }` — the one node of a type.\n- `{ kind: \"node\", nodeId }` — a specific node.\n- `{ kind: \"subject\" }` — the page's `subjectNodeId` anchor.\n- `{ kind: \"traverse\", from, edgeCatalogKey, direction }` — related nodes.\n- `{ kind: \"ref\", binding }` — alias another binding.\n- `{ kind: \"artifact\", nodeId?/ref? }` — a Widget artifact.\n\n## Actions (writes)\n\n`actions` is a map of `actionKey -> def`. Form `Button`s and bound inputs\n(`Input`/`Textarea`/`Select`/`TokenList`/`DocumentEditor`) reference one via\n`props.action` to persist changes.\n\n## Authoring loop\n\n1. `list_page_components` → pick components; `get_page_component` for each\n   you'll use (copy its `example`).\n2. Define `bindings` for the data the page reads.\n3. Build `elements` (start from examples), wire `props.binding` / `props.action`.\n4. `create_page` (validates component keys); iterate with `update_page`.\n\nCompose existing components; you cannot define new component types from chat —\nuse `Widget` only as a last-resort escape hatch.\n",
  "agent.guide.workflow_authoring.md": "# agent.guide.workflow_authoring\n\nReference for authoring workflows with `write_workflow_instruction`. Load this\nwhen you need to define a project workflow; it is not a task to route.\n\n## What a workflow is\n\nA reusable playbook the agent (or a spawned task executor) follows for a\nrecurring process. Each workflow you write appears in \"Available workflows\" on\nthe next turn and becomes routable by its `description`.\n\n## Fields\n\n- `key` — stable, namespaced, lower_snake. Use `work.<verb_noun>` for execution\n  playbooks (e.g. `work.onboard_customer`), `orchestrator.<cadence>` for\n  recurring review loops. Re-writing the same key updates in place (upsert).\n- `name` — short human title.\n- `description` — a skill-style \"when to use this\" line. THIS is the routing\n  signal: be specific about the trigger situation, not the mechanics. Good:\n  \"Use when a new customer signs up and needs onboarding tasks created.\" Weak:\n  \"Customer workflow.\"\n- `body` — the playbook as markdown.\n\n## Body structure\n\nKeep it single-purpose and concrete:\n\n1. Purpose — one line.\n2. When to run — the trigger conditions.\n3. Steps — numbered, each naming the tool(s) to call (query_nodes, create_node,\n   spawn_task, create_page, …) and the decision at each point.\n4. Completion — what \"done\" looks like / what to update.\n\n## Tips\n\n- One workflow = one job. Split multi-purpose playbooks into separate keys.\n- Reference graph types by their catalog keys; create the catalog first if\n  missing (create_node_type / create_edge_type).\n- For delegated/background work, have the workflow `spawn_task` with a full\n  executionDirective rather than doing everything inline.\n",
  "agent.setup.md": "# agent.setup\n\n## Purpose\n\nStand up a project from scratch — or reconfigure an existing one — by learning\nthe organization's domain and goals, then creating the workflows and pages that\nlet the project operate. This is the agent's own setup playbook; it ships in\ncode and is available in every project without being seeded.\n\n## When to run\n\n- The project has no workflows yet (only this built-in one appears in Available\n  workflows).\n- The user wants to (re)configure how the project / organization operates.\n- The user describes a new domain, goal, or recurring process to support.\n\n## Steps\n\n1. **Survey, then interview** — first call `delegate` with `subagentType:\n   \"explorer\"` to summarize what already exists in this project (catalog, pages,\n   workflows, tasks) so you build on it instead of duplicating. Then understand\n   the domain in a few focused turns (don't over-question), establishing:\n   - What the organization / domain is, and its primary goal right now.\n   - The main \"things\" it tracks — these become node records.\n   - The recurring processes or jobs it needs, and on what cadence.\n   - Who does the work — you (Agent), the user, or other people (executor types).\n2. **Confirm a plan** — restate, briefly, the catalog, workflows, and pages you\n   intend to create, and get the user's agreement before writing anything\n   substantial.\n3. **Model the catalog** — define the domain's record and relationship types\n   first (instances and pages depend on them). Call `list_node_types` to see\n   what exists, then `create_node_type` for each kind of record (e.g.\n   `customer`, `invoice`) with a `propertySchema`, and `create_edge_type` for\n   each relationship (e.g. `placed_by`), using node-type keys for\n   `domainKeys` / `rangeKeys`.\n4. **Author workflows** — for each recurring process, call\n   `write_workflow_instruction` with: a clear `key` (e.g. `work.<verb>`), a\n   skill-style `description` (\"when to use\" — routing quality depends on this),\n   and a step-by-step playbook as the `content`. New workflows appear in\n   Available workflows on the next turn and become routable.\n5. **Build pages** — for each surface the user needs, call `create_page` with a\n   json-render definition (root + elements, bindings to graph data, actions).\n   Use `update_page` to iterate. Compose existing component types; you cannot\n   define new component types from chat.\n6. **Seed the graph** — if workflows or pages assume starting records, create\n   them with `create_node` / `create_edge` (their types must exist in the\n   catalog from step 3).\n7. **Hand off** — summarize what now exists (catalog, workflows, pages, key\n   nodes) and how the user can use it. Spawn tasks only for work that should run\n   now.\n\n## Reference guides (load on demand)\n\nFor details, load these with `get_workflow_instruction` when you reach the\nrelevant step — don't inline them up front:\n\n- `agent.guide.workflow_authoring` — how to write good workflows (step 4).\n- `agent.guide.page_authoring` — the json-render page format (step 5); also call\n  `list_page_components` / `get_page_component` for the live component catalog.\n\n## Notes\n\n- Re-running setup is safe: `write_workflow_instruction` upserts by key, and a\n  project row with the same key as a built-in overrides the built-in.\n- Keep each workflow single-purpose with a precise description.\n- Do not claim a workflow or page exists until the tool call confirms it.\n",
  "orchestrator.bootstrap.md": "# orchestrator.bootstrap\n\n## Purpose\n\nOne-time setup: document external automation hooks (Cursor/Claude/Codex) and verify ssota MCP connectivity for the project.\n\n## When to run\n\n- Manual Human trigger, or first dogfood session\n- After project automation configuration changes\n\n## Preconditions\n\n- MCP `list_projects` / `get_project` succeeds for the target project\n- Bearer auth and `X-SSOTA-Project-Id` (or OAuth project context) configured\n\n## Steps\n\n1. Call MCP `query_tasks` with `workflowKey=orchestrator.bootstrap` and `status` in `running|ready` — skip if an open bootstrap task already exists (use idempotency).\n2. Record in task `result` the automation checklist:\n   - daily → `orchestrator.daily`\n   - weekly → `orchestrator.weekly`\n   - monthly → `orchestrator.monthly`\n   - watchdog → `orchestrator.watchdog`\n3. Optionally `spawn_task` a single `orchestrator.daily` task with `idempotencyKey=bootstrap:daily:{date}` if backlog is empty.\n4. `update_task` this task to `done` with summary in `result`.\n\n## MCP tools\n\n- `query_tasks`, `spawn_task`, `update_task`, `get_project`\n\n## Spawn rules\n\n- Do not spawn work tasks during bootstrap unless explicitly requested in `context`.\n\n## Completion\n\n- `status=done`\n- `result` contains automation checklist and MCP smoke status\n\n## Escalation\n\n- If MCP auth fails → `status=blocked`, `assignee` Human operator\n",
  "orchestrator.daily.md": "# orchestrator.daily\n\n## Purpose\n\nReview project task backlog and spawn today's work items for agents or humans.\n\n## When to run\n\n- External automation cron (e.g. daily 09:00)\n- Manual trigger with `workflowKey=orchestrator.daily`\n\n## Preconditions\n\n- Project context resolved\n- No duplicate run for same calendar day (`idempotencyKey=daily:{YYYY-MM-DD}` on orchestrator summary task optional)\n\n## Steps\n\n1. `query_tasks` — `status` in `ready`, `running`, `blocked`; note stale `running` (>24h `updatedAt`).\n2. `query_tasks` — `status=pending`, `executorType=Agent`, prioritize by `updatedAt`.\n3. For each planned work item, `spawn_task` with:\n   - `workflowKey` from `work.*` or initiative steward keys\n   - `status=ready` for Agent work\n   - `idempotencyKey=daily:{date}:{workflowKey}:{slug}`\n4. If stale running tasks found, `spawn_task` `orchestrator.watchdog` or `work.unblock` child with watchdog idempotency.\n5. `update_task` orchestrator run task with `result.summary` (counts spawned, skipped, stale).\n\n## MCP tools\n\n- `query_tasks`, `spawn_task`, `update_task`\n\n## Spawn rules\n\n- Prefer `work.implement_feature`, `work.write_document` for concrete execution\n- Do not spawn duplicate work if `idempotencyKey` already exists\n\n## Completion\n\n- `status=done`\n- `result.spawned`, `result.skipped`, `result.stale` tallies\n\n## Escalation\n\n- Ambiguous priority → spawn Human task with `executorType=Human`\n",
  "orchestrator.monthly.md": "# orchestrator.monthly\n\n## Purpose\n\nMonthly retrospective and backlog grooming at project level.\n\n## When to run\n\n- External automation cron (e.g. 1st of month 09:00)\n\n## Preconditions\n\n- Project context resolved\n\n## Steps\n\n1. `query_tasks` — `status=done` in last 30 days; summarize throughput in `result`.\n2. `query_tasks` — long-lived `pending`/`blocked`; propose archive or Human review tasks.\n3. `spawn_task` monthly initiative review if `context.initiativeId` present.\n4. `update_task` monthly summary.\n\n## MCP tools\n\n- `query_tasks`, `spawn_task`, `update_task`\n\n## Completion\n\n- `status=done`\n",
  "orchestrator.watchdog.md": "# orchestrator.watchdog\n\n## Purpose\n\nDetect stalled tasks and spawn recovery or nudge work items.\n\n## When to run\n\n- Every 6h or daily afternoon automation\n- Invoked from `orchestrator.daily` when stale tasks detected\n\n## Preconditions\n\n- Project context resolved\n\n## Steps\n\n1. `query_tasks` — `status=running` with `updatedAt` older than 24h.\n2. `query_tasks` — `status=ready`, `executorType=Agent`, `createdAt` older than 48h.\n3. `query_tasks` — `status=blocked` where `context.escalation` is not true.\n4. For each candidate, `spawn_task`:\n   - `workflowKey=work.unblock` or re-queue same `workflowKey`\n   - `idempotencyKey=watchdog:{taskId}:{YYYY-MM-DD}`\n   - `parentTaskId` = stalled task id\n5. `update_task` watchdog run with `result.candidates` list.\n\n## MCP tools\n\n- `query_tasks`, `spawn_task`, `update_task`\n\n## Completion\n\n- `status=done`\n\n## Escalation\n\n- Repeated stall on same task → `executorType=Human` spawn\n",
  "orchestrator.weekly.md": "# orchestrator.weekly\n\n## Purpose\n\nWeekly planning pass: align tasks with initiatives, schedule larger work chunks, close stale items.\n\n## When to run\n\n- External automation cron (e.g. Monday 09:00)\n\n## Preconditions\n\n- Project context resolved\n\n## Steps\n\n1. `query_tasks` — all non-terminal statuses; group by `workflowKey`.\n2. Review `blocked` and `failed` — spawn recovery or Human triage tasks.\n3. `spawn_task` for weekly goals not yet represented in queue (`idempotencyKey=weekly:{YYYY-Www}:{key}`).\n4. `update_task` with weekly summary in `result`.\n\n## MCP tools\n\n- `query_tasks`, `spawn_task`, `update_task`\n\n## Completion\n\n- `status=done`, `result` documents weekly plan\n",
  "work.implement_feature.md": "# work.implement_feature\n\n## Purpose\n\nImplement a single scoped feature or fix linked to a task.\n\n## When to run\n\n- Task `status=ready`, spawned by orchestrator or Human\n- Agent picks from `query_tasks(status=ready, workflowKey=work.implement_feature)`\n\n## Preconditions\n\n- Task has clear `title` and `acceptanceCriteria`\n- Repo/automation context available in agent environment (not SSOTA responsibility)\n\n## Steps\n\n1. `get_task` — load full context.\n2. `update_task` — `status=running`, set `context.lockOwner` if needed.\n3. Execute implementation per acceptance criteria in agent environment.\n4. `update_task` — `status=done` or `blocked`/`failed` with `result` (PR link, summary).\n\n## MCP tools\n\n- `get_task`, `update_task`, optionally `spawn_task` for subtasks\n\n## Completion\n\n- All `acceptanceCriteria` met → `status=done`\n- External blocker → `status=blocked`\n",
  "work.unblock.md": "# work.unblock\n\n## Purpose\n\nRecover a stalled or blocked task: nudge assignee, re-queue, or escalate to Human.\n\n## When to run\n\n- Spawned by `orchestrator.watchdog` with `parentTaskId` set\n\n## Preconditions\n\n- `parentTaskId` references an existing task in the same project\n\n## Steps\n\n1. `get_task` for `parentTaskId`\n2. Assess stall reason from parent `status`, `result`, `context`\n3. If agent can proceed: `update_task` parent → `status=ready`, clear lock in `context`\n4. If Human needed: `spawn_task` with `executorType=Human` or `update_task` parent → `blocked`\n5. `update_task` this task → `done` with `result.action` taken\n\n## MCP tools\n\n- `get_task`, `update_task`, `spawn_task`\n\n## Completion\n\n- Parent unblocked or escalated → `status=done`\n",
  "work.write_document.md": "# work.write_document\n\n## Purpose\n\nProduce or update a graph document node for a task (SSOTA Console content).\n\n## When to run\n\n- Task `status=ready`, `workflowKey=work.write_document`\n\n## Preconditions\n\n- Task has clear `title` and `acceptanceCriteria`\n- Target known via `targetNodeId` or `context.nodeId` + optional `context.nodeType`\n\n## Steps\n\n1. `get_task` — load full context\n2. `update_task` — `status=running`\n3. If `targetNodeId` (or `context.nodeId`) is set:\n   - `get_node` — read current content\n   - `update_node` — patch `title`, `content`, `properties` per acceptance criteria\n4. Else if `context.nodeType` is set:\n   - `create_node` — new node with `content` from acceptance criteria\n   - `update_task` — set `targetNodeId` to created node id\n5. `update_task` — `status=done`, `result` with `nodeId` and summary\n\n## MCP tools\n\n- `get_task`, `update_task`, `get_node`, `update_node`, `create_node`\n\n## Completion\n\n- `status=done` with `result.nodeId` and content summary\n- External blocker → `status=blocked`\n",
};
